-- Orion: scheduled jobs (pg_cron)
--
-- Every job reads its settings from Supabase Vault, so nothing project-specific lives in this file.
-- Before these jobs can do anything, add three secrets in Supabase -> Project Settings -> Vault:
--   SUPABASE_URL       your project URL, e.g. https://abcdefghijklmnop.supabase.co
--   SUPABASE_ANON_KEY  your project's anon (public) key
--   cron_secret        a long random string; set the same value as the CRON_SECRET edge function secret
-- Jobs whose edge function you haven't deployed or configured simply return an error and retry next run.

CREATE OR REPLACE FUNCTION public.orion_secret(p_name text)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $$ SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = p_name LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.orion_secret(text) FROM PUBLIC, anon, authenticated;

SELECT cron.schedule('agent-liveness-alarm-cron', '*/10 * * * *', 'SELECT net.http_post(url := public.orion_secret(''SUPABASE_URL'') || ''/functions/v1/agent-liveness-alarm'', headers := jsonb_build_object(''Content-Type'', ''application/json'', ''Authorization'', ''Bearer '' || public.orion_secret(''SUPABASE_ANON_KEY'')), body := ''{"source":"cron"}''::jsonb, timeout_milliseconds := 30000);');
SELECT cron.schedule('agent-thread-sweep', '* * * * *', 'SELECT net.http_post(url := public.orion_secret(''SUPABASE_URL'') || ''/functions/v1/agent-thread'', headers := jsonb_build_object(''Content-Type'', ''application/json'', ''X-Cron-Secret'', public.orion_secret(''cron_secret'')), body := ''{"sweep": true}''::jsonb, timeout_milliseconds := 30000);');
